//! The screens' TypeScript types, generated from the API's Rust types.
//!
//! The types the screens read or send derive `ts_rs::TS` in the tests' builds
//! (`#[cfg_attr(test, derive(ts_rs::TS))]`; in the feature crates, behind their
//! `ts` feature, which this crate's dev-dependencies turn on), so the app itself
//! never builds ts-rs. [`roots`] names the types the generated files start from;
//! every type they hold is generated with them, one file per type plus an
//! `index.ts` that exports them all, in [`COMMITTED`].
//!
//! The files are committed because the image stage that builds the screens has
//! no Rust. [`committed_files_are_current`] fails when generating would give
//! other files than the committed ones, and writes nothing. To write them
//! again after a change to one of the types, run from the repository root:
//!
//! ```sh
//! cargo types
//! ```
//!
//! An API type is added to the screens by deriving `TS` on it and naming it, or
//! a type that holds it, in [`roots`].

use std::{
    any::TypeId,
    collections::BTreeMap,
    fs,
    path::{Path, PathBuf},
};

use ts_rs::{Config, TypeVisitor, TS};

use super::{
    archive_api, channels_api, commands_api, error, history_api, past_search_api, rules_api,
    save_folder_api, schedule_api, setup_api, status_api, subscriptions_api,
};

/// Where the generated files are committed.
const COMMITTED: &str = "../../web/src/lib/api-types";

const NOTE: &str = "// This file was generated by `cargo types` from the API's Rust types (`crates/trss/src/web/api_types.rs`). Do not edit this file manually.\n";

fn committed_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join(COMMITTED)
}

/// The types the generated files start from: what the screens read from the API
/// or send to it. The types they hold are generated with them.
fn roots(v: &mut impl TypeVisitor) {
    v.visit::<error::ErrorBody>();
    v.visit::<commands_api::CommandRequest>();
    v.visit::<commands_api::CommandView>();
    v.visit::<archive_api::SuggestionList>();
    v.visit::<archive_api::KeepBody>();
    v.visit::<archive_api::Kept>();
    v.visit::<channels_api::ChannelList>();
    v.visit::<channels_api::ChannelView>();
    v.visit::<channels_api::CreateBody>();
    v.visit::<channels_api::UpdateBody>();
    v.visit::<channels_api::Removed>();
    v.visit::<history_api::HistoryList>();
    v.visit::<history_api::HistoryItemView>();
    v.visit::<past_search_api::Context>();
    v.visit::<past_search_api::StartBody>();
    v.visit::<past_search_api::Started>();
    v.visit::<past_search_api::RangeBody>();
    v.visit::<past_search_api::RangeLabel>();
    v.visit::<past_search_api::Poll>();
    v.visit::<rules_api::RuleList>();
    v.visit::<rules_api::RuleView>();
    v.visit::<rules_api::RuleGroup>();
    v.visit::<rules_api::Removed>();
    v.visit::<rules_api::CreateBody>();
    v.visit::<rules_api::UpdateBody>();
    v.visit::<rules_api::OrderBody>();
    v.visit::<rules_api::SwitchBody>();
    v.visit::<rules_api::ArchivedWorkAnswer>();
    v.visit::<rules_api::PreviewBody>();
    v.visit::<rules_api::Preview>();
    v.visit::<rules_api::episode::EpisodeBody>();
    v.visit::<save_folder_api::WorksAnswer>();
    v.visit::<save_folder_api::SuggestionAnswer>();
    v.visit::<schedule_api::Answer>();
    v.visit::<setup_api::FirstRunView>();
    v.visit::<setup_api::SkipBody>();
    v.visit::<status_api::Board>();
    v.visit::<subscriptions_api::Schedule>();
    v.visit::<subscriptions_api::Creators>();
    v.visit::<subscriptions_api::SubscriptionList>();
    v.visit::<subscriptions_api::Titles>();
    v.visit::<subscriptions_api::CandidateList>();
    v.visit::<subscriptions_api::RejectBody>();
    v.visit::<subscriptions_api::Rejected>();
    v.visit::<subscriptions_api::TitleBody>();
    v.visit::<subscriptions_api::SubscribeBody>();
    v.visit::<subscriptions_api::Subscribed>();
    v.visit::<subscriptions_api::CreatorBody>();
    v.visit::<subscriptions_api::LinkBody>();
}

/// Writes every type of [`roots`] and the types they hold into `dir`, one file
/// each, and an `index.ts` that exports them. Two Rust types that would give
/// the same TypeScript name fail here instead of one hiding the other.
fn generate(dir: &Path) {
    struct Collect<'a> {
        config: &'a Config,
        /// TypeScript name to the Rust type that has it.
        seen: BTreeMap<String, (TypeId, &'static str)>,
    }

    impl TypeVisitor for Collect<'_> {
        fn visit<T: TS + 'static + ?Sized>(&mut self) {
            // A primitive or a wrapper such as `Vec` has no file.
            if T::output_path().is_none() {
                return;
            }
            let name = T::ident(self.config);
            let rust = std::any::type_name::<T>();
            if let Some((id, first)) = self.seen.get(&name) {
                assert!(
                    *id == TypeId::of::<T>(),
                    "`{first}` and `{rust}` are both `{name}` in TypeScript: rename one with #[ts(rename = \"...\")]"
                );
                return;
            }
            self.seen.insert(name, (TypeId::of::<T>(), rust));
            T::export(self.config).expect("a type is written");
            T::visit_dependencies(self);
        }
    }

    fs::create_dir_all(dir).expect("the directory is made");
    // Integers are `number`: the screens read them as such, and none of the
    // API's reaches 2^53.
    let config = Config::new().with_large_int("number").with_out_dir(dir);
    let mut collect = Collect {
        config: &config,
        seen: BTreeMap::new(),
    };
    roots(&mut collect);

    let mut index = String::from(NOTE);
    for name in collect.seen.keys() {
        index.push_str(&format!("export type {{ {name} }} from \"./{name}\";\n"));
    }
    fs::write(dir.join("index.ts"), index).expect("the index is written");
}

/// Every file of `dir` by name.
fn read_dir(dir: &Path) -> BTreeMap<String, String> {
    let Ok(entries) = fs::read_dir(dir) else {
        return BTreeMap::new();
    };
    entries
        .map(|entry| {
            let path = entry.expect("an entry is read").path();
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            (name, fs::read_to_string(&path).expect("a file is read"))
        })
        .collect()
}

/// What differs between the generated files and the committed ones, one line
/// each; empty when they are the same.
fn differences(
    generated: &BTreeMap<String, String>,
    committed: &BTreeMap<String, String>,
) -> Vec<String> {
    let mut lines = Vec::new();
    for (name, text) in generated {
        match committed.get(name) {
            None => lines.push(format!("missing: {name}")),
            Some(old) if old != text => lines.push(format!("changed: {name}")),
            Some(_) => {}
        }
    }
    for name in committed.keys() {
        if !generated.contains_key(name) {
            lines.push(format!("stale: {name}"));
        }
    }
    lines
}

#[test]
fn committed_files_are_current() {
    let temp = tempfile::tempdir().expect("a temporary directory");
    generate(temp.path());
    let committed = committed_dir();
    let lines = differences(&read_dir(temp.path()), &read_dir(&committed));
    assert!(
        lines.is_empty(),
        "the generated TypeScript types in {COMMITTED} are not the ones the Rust types give; run `cargo types` from the repository root and commit the result:\n{}",
        lines.join("\n")
    );
}

/// Writes the committed files again; `cargo types` runs only this.
#[test]
#[ignore = "writes web/src/lib/api-types; run it with `cargo types`"]
fn write_committed_files() {
    let committed = committed_dir();
    if committed.exists() {
        fs::remove_dir_all(&committed).expect("the old files are removed");
    }
    generate(&committed);
}

#[test]
fn command_requests_are_the_ones_the_web_reads() {
    use serde_json::json;
    use trss_collect::commands::{
        anissia_captions::{self, AnissiaCaptions},
        episode_undo::{self, EpisodeUndo},
        receive_once::{self, ReceiveOnce},
        receive_past,
        rule_archive::{self, Direction, RuleArchive},
    };
    use trss_library::watch_rescan::{self, WatchRescan};

    use super::commands_api::{CommandKind, CommandPayload, CommandRequest, PastRequest, Request};

    // The kind each request the server reads is listed under. It has no
    // wildcard, so a `Request` added without its `CommandKind` does not
    // compile.
    fn listed(request: &Request) -> CommandKind {
        match request {
            Request::ReceiveOnce(_) => CommandKind::ReceiveOnce,
            Request::ReceivePast(_) => CommandKind::ReceivePast,
            Request::RuleArchive(_) => CommandKind::RuleArchive,
            Request::WatchRescan(_) => CommandKind::WatchRescan,
            Request::EpisodeUndo(_) => CommandKind::EpisodeUndo,
            Request::AnissiaCaptions(_) => CommandKind::AnissiaCaptions,
        }
    }

    let sent = [
        (
            receive_once::KIND,
            CommandKind::ReceiveOnce,
            CommandPayload::ReceiveOnce(ReceiveOnce::new(7)),
        ),
        (
            receive_past::KIND,
            CommandKind::ReceivePast,
            CommandPayload::ReceivePast(PastRequest {
                rule_id: "r".into(),
                search_id: "s".into(),
                key: "k".into(),
            }),
        ),
        (
            rule_archive::KIND,
            CommandKind::RuleArchive,
            CommandPayload::RuleArchive(RuleArchive {
                rule_id: "r".into(),
                direction: Direction::Archive,
                receive: Vec::new(),
            }),
        ),
        (
            watch_rescan::KIND,
            CommandKind::WatchRescan,
            CommandPayload::WatchRescan(WatchRescan {
                folder_id: "f".into(),
            }),
        ),
        (
            episode_undo::KIND,
            CommandKind::EpisodeUndo,
            CommandPayload::EpisodeUndo(EpisodeUndo {
                rule_id: "r".into(),
                episode: 3,
            }),
        ),
        (
            anissia_captions::KIND,
            CommandKind::AnissiaCaptions,
            CommandPayload::AnissiaCaptions(AnissiaCaptions { anime_no: 5 }),
        ),
    ];
    for (kind, listed_kind, command) in sent {
        assert_eq!(serde_json::to_value(&listed_kind).unwrap(), json!(kind));
        let body = serde_json::to_value(CommandRequest {
            id: "command-1".into(),
            command,
        })
        .unwrap();
        assert_eq!(body["id"], "command-1");
        assert_eq!(body["kind"], kind);
        let request = Request::read(kind, body["payload"].clone())
            .unwrap_or_else(|_| panic!("the web does not read the `{kind}` payload"));
        assert_eq!(request.kind(), kind);
        assert_eq!(
            serde_json::to_value(listed(&request)).unwrap(),
            serde_json::to_value(listed_kind).unwrap()
        );
    }
}

/// The enums that took the place of a `code()` string in a response send the
/// same text, so the JSON did not change.
#[test]
fn enums_serialize_as_their_codes() {
    use serde_json::json;
    use trss_collect::{
        commands::rule_archive::Direction,
        past_search::judge::State,
        plan::PastCause,
        store::{
            channels::{RuleState, SubtitleMode, UndoFileState},
            history::HistoryResult,
        },
    };
    use trss_core::commands::CommandState;
    use trss_library::store::setup::Step;

    use super::{archive_api::GroundKind, past_search_api::PollState, rules_api::HeldBy};

    fn same<T: serde::Serialize + Copy>(all: &[T], code: impl Fn(T) -> &'static str) {
        for one in all {
            assert_eq!(serde_json::to_value(one).unwrap(), json!(code(*one)));
        }
    }

    same(&HistoryResult::ALL, HistoryResult::code);
    same(&Step::ALL, Step::code);
    same(
        &[
            State::Missing,
            State::Replace,
            State::VersionUnknown,
            State::Have,
            State::Superseded,
            State::Alternate,
            State::Batch,
            State::Unnumbered,
        ],
        State::code,
    );
    same(
        &[RuleState::Active, RuleState::Paused, RuleState::Archived],
        RuleState::as_str,
    );
    same(
        &[
            SubtitleMode::Follow,
            SubtitleMode::Undecided,
            SubtitleMode::None,
        ],
        SubtitleMode::as_str,
    );
    same(
        &[
            Direction::Archive,
            Direction::Restore,
            Direction::Start,
            Direction::Resume,
        ],
        Direction::code,
    );
    same(
        &[
            CommandState::Pending,
            CommandState::Running,
            CommandState::Done,
            CommandState::Failed,
        ],
        CommandState::code,
    );
    same(
        &[
            PastCause::Subscribed,
            PastCause::Titled,
            PastCause::Resumed,
            PastCause::FirstRead,
        ],
        PastCause::code,
    );
    same(
        &[
            UndoFileState::Pending,
            UndoFileState::Renamed,
            UndoFileState::Kept,
        ],
        UndoFileState::code,
    );

    // These took the place of string literals, not of a `code()`.
    for (one, text) in [
        (GroundKind::Ended, "ended"),
        (GroundKind::Unlisted, "unlisted"),
        (GroundKind::Quiet, "quiet"),
    ] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
    for (one, text) in [
        (HeldBy::Subscription, "subscription"),
        (HeldBy::Link, "link"),
    ] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
    for (one, text) in [
        (PollState::Running, "running"),
        (PollState::Failed, "failed"),
        (PollState::Done, "done"),
    ] {
        assert_eq!(serde_json::to_value(one).unwrap(), json!(text));
    }
}

/// `ErrorBody` replaced `json!` bodies: `current` is absent when there is none
/// and `null` only when the server's value is `null`, as the `json!` built them
/// (`"current"` was left out unless a handler had a value).
#[test]
fn error_body_keeps_current_absent_or_null_as_before() {
    use serde_json::{json, Value};

    use super::error::{AlreadySubscribed, ErrorBody, ErrorCode};

    let none = serde_json::to_value(ErrorBody::new(ErrorCode::Invalid, "m")).unwrap();
    assert_eq!(none, json!({"error": "invalid", "message": "m"}));
    assert!(none.get("current").is_none());

    let mut null = ErrorBody::new(ErrorCode::Conflict, "m");
    null.current = Some(Value::Null);
    let null = serde_json::to_value(null).unwrap();
    assert_eq!(
        null,
        json!({"error": "conflict", "message": "m", "current": null})
    );
    assert!(null.get("current").is_some());

    let rule = serde_json::to_value(AlreadySubscribed {
        rule_id: "r1".into(),
    })
    .unwrap();
    assert_eq!(rule, json!({"rule_id": "r1"}));

    for (code, text) in [
        (ErrorCode::NotFound, "not_found"),
        (ErrorCode::Unavailable, "unavailable"),
        (ErrorCode::Internal, "internal"),
        (ErrorCode::HostNotAllowed, "host_not_allowed"),
        (ErrorCode::Forbidden, "forbidden"),
        (ErrorCode::Gone, "gone"),
    ] {
        assert_eq!(serde_json::to_value(code).unwrap(), json!(text));
    }
}
